def _load_baseline(path: Path, required_status: str | None = None) -> dict:
    raw = path.read_bytes()
    digest = digest_bytes(raw)
    trusted = {
        "candidate": CANDIDATE_BASELINE_SHA256,
        "frozen": FROZEN_BASELINE_SHA256,
    }
    manifest = json.loads(raw)
    status = manifest.get("status")
    if (
        type(status) is not str
        or status not in trusted
        or trusted[status] is None
        or digest != trusted[status]
    ):
        raise ValueError("Untrusted baseline digest")
    if required_status is not None and status != required_status:
        raise ValueError("Baseline status differs from required release")
    if manifest.get("version") != REPORT_VERSION or manifest.get("timing_model") != TIMING_MODEL:
        raise ValueError("Incompatible baseline manifest")
    current = provenance(baseline_hardware(), _baseline_programs())
    if manifest.get("provenance") != current:
        raise ValueError("Baseline source, cost, workload, hardware or program hash changed")
    if set(manifest.get("baseline_cycles", {})) != set(CASES) or any(
        type(value) is not int or value <= 0 for value in manifest["baseline_cycles"].values()
    ):
        raise ValueError("Invalid baseline cycles")
    if manifest.get("clock_hz") != cost_model()["clock_hz"] or any(
        manifest.get("baseline_metrics", {}).get(case, {}).get("cycles")
        != manifest["baseline_cycles"][case]
        for case in CASES
    ):
        raise ValueError("Baseline metrics or clock differ")
    checks = manifest.get("functional_checks", {})
    if set(checks) != set(CASES) or any(
        checks[case].get("seed_sha256") != manifest.get("functional_seed_sha256")
        or checks[case].get("passed") is not True
        for case in CASES
    ):
        raise ValueError("Baseline functional evidence differs")
    reference_runtime = manifest.get("runtime_environment", {})
    current_runtime = runtime_environment()
    if any(reference_runtime.get(key) != current_runtime[key] for key in ("python", "numpy")):
        raise ValueError("Baseline numerical runtime differs")
    stable_report(manifest)
    return manifest
def check_case(case: str, seed: int, hardware: Hardware, program: str) -> dict:
    validate_hbm_races(program)
    fixture = make_fixture(case, seed, hardware, program)
    result = fixture.machine.execute(iter_parse(program), hbm_races_validated=True)
    model = MODELS[case.split("_")[0]]
    expected_hidden, expected_kv = run_scenario(model, case.split("_")[1], seed)
    expected = {"output/hidden": expected_hidden}
    for layer, (key, value) in enumerate(expected_kv):
        expected[f"layer{layer}/new_k"] = key
        expected[f"layer{layer}/new_v"] = value
    checks = {}
    for name, oracle in expected.items():
        symbol = fixture.layout.symbols[name]
        start = symbol.address // 4
        actual = result[start : start + oracle.size].reshape(oracle.shape)
        delta = np.abs(actual.astype(np.float64) - oracle.astype(np.float64))
        finite_error = bool(np.isfinite(delta).all())
        all_written = all(
            index in fixture.machine.written_hbm for index in range(start, start + oracle.size)
        )
        checks[name] = {
            "max_absolute_error": float(delta.max()) if finite_error else None,
            "allclose_1e-3_1e-3": finite_error
            and bool(np.allclose(actual, oracle, rtol=1e-3, atol=1e-3)),
            "all_elements_written": all_written,
        }
    return {
        "seed_sha256": seed_digest(seed),
        "passed": all(
            value["allclose_1e-3_1e-3"] and value["all_elements_written"]
            for value in checks.values()
        ),
        "checks": checks,
    }


def estimate_case(case: str, hardware: Hardware, program: str) -> dict:
    model = MODELS[case.split("_")[0]]
    layout = build_layout(model, case.split("_")[1])
    words = required_hbm_words(program, layout)
    timing = estimate_pipeline(
        hardware, iter_parse(program), words, step_requirements(case, layout)
    )
    return asdict(timing)


def evaluate_submission(
    mode: str,
    hardware: Hardware,
    programs: dict[str, str],
    seeds: list[int],
    baseline: dict | None = None,
) -> dict:
    """Run the same timing path for estimate, check and candidate grade."""
    if mode not in {"estimate", "check", "grade"}:
        raise ValueError("Unknown challenge mode")
    if set(programs) != set(CASES):
        raise ValueError("Both challenge programs are required")
    if mode != "estimate" and not seeds:
        raise ValueError("Functional modes require seeds")
    if mode == "grade" and baseline is None:
        raise ValueError("Grade requires a baseline manifest")
    seed_hashes = [seed_digest(seed) for seed in seeds]
    report = {
        "version": REPORT_VERSION,
        "mode": mode,
        "timing_model": TIMING_MODEL,
        "status": "candidate",
        "seed_source": "local_public",
        "provenance": provenance(hardware, programs),
        "seed_sha256": seed_hashes,
        "cases": {},
        "score": None,
    }
    for case in CASES:
        checks = []
        if mode != "estimate":
            for seed in seeds:
                try:
                    checks.append(check_case(case, seed, hardware, programs[case]))
                except (ValueError, FloatingPointError, IndexError, KeyError, TypeError) as exc:
                    checks.append(
                        {"seed_sha256": seed_digest(seed), "passed": False, "error": str(exc)}
                    )
        passed = all(check["passed"] for check in checks) if checks else False
        report["cases"][case] = {"functional": checks, "functional_passed": passed}
    for case in CASES:
        if not any("error" in check for check in report["cases"][case]["functional"]):
            try:
                report["cases"][case]["timing"] = estimate_case(case, hardware, programs[case])
            except (ValueError, FloatingPointError, IndexError, KeyError, TypeError) as exc:
                report["cases"][case]["timing_error"] = str(exc)
    if mode == "grade":
        if any("timing" not in report["cases"][case] for case in CASES):
            report["eligible"] = False
            report["experimental_score"] = None
            return report
        if baseline["timing_model"] != TIMING_MODEL or set(baseline["baseline_cycles"]) != set(
            CASES
        ):
            raise ValueError("Baseline timing model or cases differ")
        measured = {
            case: ScenarioMetric(
                report["cases"][case]["timing"]["cycles"],
                report["cases"][case]["timing"]["peak_window_power_w"],
                report["cases"][case]["functional_passed"],
            )
            for case in CASES
        }
        score = evaluate_score(hardware.area_mm2(), measured, baseline["baseline_cycles"])
        report["gate_diagnostics"] = score
        report["experimental_score"] = score["score"]
        report["eligible"] = score["eligible"]
    return report


def write_report(path: Path, report: dict) -> None:
1. `FOR ...m` selects up to eight rows; `FOR ...n` selects 16 output columns.
2. `VEC add` of two zero immediates initializes the RF accumulator. `MMA.ACC` adds to the existing accumulator; skipping initialization changes the answer or reads unwritten RF.
3. `FOR ...k` visits the K dimension in 48-element chunks. Two `LD` instructions bring the A and B tiles from HBM to RF. Their `shape`/`strides` preserve the source matrices' row-major layout.
4. `MMA.ACC` multiplies those RF tiles and accumulates into RF lane 2. The final K chunk uses `min(48, remaining K)` to avoid out-of-range elements.
5. `ST` writes the accumulated tile to its HBM scratch output.

A long expression such as `{"min":[48,{"add":[256,{"mul":[-1,{"var":"...k"}]}]}]}` means `min(48, 256 - k)`. It is a **compile-time integer expression** used for the final tile size. `{"var":"...k"}` substitutes the current static loop index; braces in an event name interpolate that index into a unique string. See the [ISA expression rules](/isa/#static-loops-and-expressions) before editing generated expressions.

## 6. Commit, event, and workgroup rules that often cause failures

- **Input release:** P1 `input/step0` is unreadable before the prompt commit. D1 `input/step{s}` is unreadable before all earlier steps commit. A correct final HBM result cannot excuse an early read.
- **Output coverage:** each required final hidden and new K/V element must be written once. A commit fails when current required output/KV positions are missing. Writing an output position twice also fails.
- **Initialized storage:** RF/SH reads require a prior write. An `MMA.ACC` accumulator must start with an initialized value. Scratch HBM must be written before it is read.
- **Events:** each expanded operation needs a unique event name. `WAIT` names earlier events and a specific workgroup; `BARRIER` names participating workgroups. Reusing an event inside expanded loops fails.
- **Cross-workgroup HBM:** two workgroups' source-line order alone does not order overlapping HBM accesses. Use synchronization with the producer's event, a barrier, or `STEP.COMMIT` as appropriate.
- **Transfer source reuse:** an `ST` may still be reading RF/SH after issue. Wait for its service to finish before overwriting an overlapping source. The timing checker enforces this dependency.
- **Program completion:** end every workgroup. P1 needs one intermediate commit; D1 needs all eight commits. Static `FOR` bodies must be well-formed even when they execute zero times.

## 7. Generate, check, and submit

The starter ZIP already contains valid files. Treat the long `.asm` listings as generated output. `project/compiler.py` is an editable copy of the baseline Python generator; leave `codesign/challenge/baseline.py` unchanged because the frozen baseline manifest checks that reference source. No C program or general-purpose compiler frontend is required.

The compiler's **inputs** are its Python source (the baseline Transformer operations and chosen software optimizations), the public model/scenario definitions in `workload_v07.json`, and HBM symbol offsets built by `abi.py`. The `Builder` methods emit ISA instructions and allocate scratch. `generate_m1_p1()` and `generate_m1_d1()` each return `(assembly_text, layout, scratch_end)`; the command below writes the first result into each `programs/*.asm` file. The compiler does not read input tensor values or automatically derive a schedule from `hardware.json`. The public checker later loads those values and evaluates your generated assembly with your selected hardware.

From the extracted starter directory, regenerate the published assembly with:

```sh
